    },
    {
      "name": "Port Check In",
      "description": "Process where passengers are verified before boarding."
    },
    {
      "name": "Onboard Activity",
      "description": "Leisure or entertainment event available on the cruise."
    },
    {
      "name": "Cruise Manager",
      "description": "Oversees ship operations, passengers, and reports."
    },
    {
      "name": "Cruise Schedule",
      "description": "Planned timeline of cruise activities and events.",
      "attributes": [
        "Onboard Activity"
      ]
    },
    {
      "name": "Activity Coordinator",
      "description": "Plans and manages onboard activities for passengers."
    },
    {
      "name": "Activity Booking",
      "description": "Passenger's reservation for an onboard activity.",
      "attributes": [
        "Onboard Activity"
      ]
    },
    {
      "name": "Medical Officer",
      "description": "Provides medical assistance and reports onboard incidents."
    },
    {
      "name": "Illness Report",
      "description": "Notification from a passenger about a health issue."
    },
    {
      "name": "Health Case Report",
      "description": "Formal report from the medical officer to management about a health case."
    }
  ]
}
